mapper.select:
SELECT FINPROD_ID hidCode, FINPROD_MARKET_ID code, FINPROD_NAME name, FINPROD_NAME shortName FROM FIN_PRODUCT
( FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{param}, '%')) OR FINPROD_NAME LIKE CONCAT('%', CONCAT(#{param}, '%')) )
AND FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND PROFIT_TYPE = #{PROFIT_TYPE}
AND TRADE_MARKET in
#{currTradeMarket}

SELECT FINPROD_ID hidCode, FINPROD_MARKET_ID code, FINPROD_NAME name, FINPROD_ABBR shortName FROM FIN_PRODUCT
( FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{param}, '%')) OR FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{param}, '%')) )
AND FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND PROFIT_TYPE = #{PROFIT_TYPE}
AND TRADE_MARKET in
#{currTradeMarket}

SELECT COUNTER_ID hidCode, COUNTER_ID code, COUNTER_NAME name, COUNTER_NAME shortName FROM MST_COUNTER_PARTY
COUNTER_NAME LIKE CONCAT('%', CONCAT(#{param}, '%'))
AND COUNTER_TYPE = #{COUNTER_TYPE}

SELECT
    CUSTOMER_ID hidCode,
    CUSTOMER_ID code,
    CUSTOMER_NAME name,
    CUSTOMER_NAME shortName
FROM MST_CUSTOMER_INFO


        (
            COUNTER_NAME LIKE CONCAT('%', CONCAT(#{param}, '%'))
            OR
            CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{param}, '%'))
        )


        AND IS_ASSTE_MANAGER = #{IS_ASSTE_MANAGER}


        AND IS_TRUSTER = #{IS_TRUSTER}


        AND IS_ISSUER = #{IS_ISSUER}


        AND IS_FINANCIER = #{IS_FINANCIER}



        AND IS_GUARANTEE = #{IS_GUARANTEE}

SELECT i.CUSTOMER_ID id, i.CUSTOMER_NAME text FROM MST_CUSTOMER_INFO i LEFT JOIN MST_CUSTOMER_INFO_ADD a on i.CUSTOMER_ID=a.CUSTOMER_ID
( i.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) OR i.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR i.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR a.INSITITUTE_CODE LIKE CONCAT('%', CONCAT(#{search}, '%')) )
( i.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{initValue}, '%')) OR i.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{initValue}, '%')) OR i.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{initValue}, '%')) OR a.INSITITUTE_CODE LIKE CONCAT('%', CONCAT(#{initValue,jdbcType=VARCHAR}, '%')) )
AND i.IS_ASSTE_MANAGER = #{IS_ASSTE_MANAGER}
AND i.IS_TRUSTER = #{IS_TRUSTER}
AND i.IS_ISSUER = #{IS_ISSUER}
AND i.IS_FINANCIER = #{IS_FINANCIER}
AND i.IS_GUARANTEE = #{IS_GUARANTEE}
AND i.IS_INVEST_ADVISER = #{IS_INVEST_ADVISER}

SELECT CALENDAR_ID id, CALENDAR_NAME text FROM MST_CALENDAR_INFO
( CALENDAR_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR CALENDAR_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND CALENDAR_ID = #{initValue}

SELECT ENTRUST_ID hidCode, ENTRUST_ID code, ENTRUST_ID name, ENTRUST_ID shortName ,PORTFOLIO_ID portfolioId /*add by songyawei*/ FROM ETR_ENTRUST
ENTRUST_ID LIKE CONCAT('%', CONCAT(#{param}, '%'))
AND ENTRUST_STATUS IN
#{item}
AND FINPROD_TYPE2 IN
#{item1}

SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object,
A.PROFIT_TYPE col
FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
(A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_ID = #{initValue}
AND A.PORTFOLIO_TYPE = #{portType01}
AND A.INVEST_YESORNO = 'Y'
AND A.PORTFOLIO_TYPE != '02'
AND A.PORTFOLIO_TYPE = #{portfolioType}
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PORTFOLIO_TYPE IN (#{portType}, #{portType1})
AND B.PORTFOLIO_SERIES = #{portfolioSeries}

SELECT DISTINCT COUNTER_ID id, COUNTER_NAME text FROM MST_COUNTER_PARTY
COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
AND COUNTER_TYPE = #{counterType}
AND COUNTER_ID = #{initValue}

SELECT DISTINCT CASH_OUT_NO id, CASH_OUT_NO text FROM INTERF_CREDIT_ITEM_INFO
CASH_OUT_NO LIKE CONCAT('%', CONCAT(#{search}, '%'))
AND CASH_OUT_NO = #{initValue}

SELECT FINPROD_ID id, FINPROD_NAME text , '01'||','||FINPROD_MARKET_ID object FROM FIN_PRODUCT
(FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')))
AND FINPROD_ID = #{initValue}
AND FINPROD_TYPE2 = #{finprodType2}

SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
(A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_ID = #{initValue}
AND A.PORTFOLIO_TYPE = #{portfolioType}
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PORTFOLIO_TYPE = #{portType}

    	SELECT
			ACCT_NO id,
			ACCT_NAME text
            /*  多级法人改造   add  by jingqiongqiong   20200616 start */
            ,SEQ_NO  seqNo
            /*  多级法人改造   add  by jingqiongqiong   20200616 end */
		FROM
			STL_CAPACCT_INFO



                (
                ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%'))
                OR
                ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
                )


                AND ACCT_NO = #{initValue}


            	AND CCY = #{ccy}

SELECT
distinct
pci.ACCT_NO id, SCI.SEQ_NO, /* add by songyawei 2020-06-18 */ sci.ACCT_NAME text FROM PTL_CAPACCT_INFO pci LEFT JOIN STL_CAPACCT_INFO sci ON pci.ACCT_NO = sci.ACCT_NO
(pci.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%'))
or sci.ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
)
AND pci.ACCT_NO = #{initValue}
AND pci.CCY = #{ccy}
AND pci.PORTFOLIO_ID = #{portfolioId}
AND pci.ACCT_TYPE = #{acctType}

SELECT distinct SCI.ACCT_NO id, SCI.SEQ_NO, /* add by songyawei 2020-06-18 */ SCI.ACCT_NAME text FROM STL_CAPACCT_INFO SCI LEFT JOIN MST_COUNTER_ACCT MCA ON SCI.ACCT_NO = MCA.ACCT_NO AND SCI.CCY = MCA.CCY
(SCI.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%'))
or SCI.ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')))
AND SCI.ACCT_NO = #{initValue}
AND SCI.CCY = #{ccy}
AND MCA.COUNTER_ID = #{counterId}
AND pci.ACCT_TYPE = #{acctType}

SELECT distinct A.FINPROD_ID id, NVL(A.FINPROD_ABBR, A.FINPROD_NAME) text, b.PAY_TYPE object
FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
INNER JOIN FIN_CASH_INFO FCI ON A.FINPROD_ID = FCI.CHL_FINPROD_ID
INNER JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID
WHERE A.IS_CHL = #{Y}
AND A.FINPROD_TYPE2 = #{F28}
AND FCI.CHL_LEVEL = 1

    AND A.FINPROD_ID = #{initValue}


    AND FP.FINPROD_MARKET_ID = #{finprodMarketId}


    AND (FP.FINPROD_ID = #{finprodId} 
         or FP.FINPROD_ID = (SELECT C.P_FINPROD_ID  FROM FIN_PRODUCT C  WHERE C.FINPROD_ID = #{finprodId} ))


    AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
    )

SELECT distinct A.FINPROD_ID id,
 NVL(A.FINPROD_ABBR, A.FINPROD_NAME) text,
 b.PAY_TYPE payType,
 b.COLLECT_TYPE collectType
FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
INNER JOIN FIN_CASH_INFO FCI ON A.FINPROD_ID = FCI.CHL_FINPROD_ID
INNER JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID
WHERE A.IS_CHL = #{Y}
AND A.FINPROD_TYPE2 = #{F28}
AND FCI.CHL_LEVEL = 1

    AND A.FINPROD_ID = #{initValue}


    AND FP.FINPROD_MARKET_ID = #{finprodMarketId}


    AND (FP.FINPROD_ID = #{finprodId} 
         or FP.FINPROD_ID = (SELECT C.P_FINPROD_ID  FROM FIN_PRODUCT C  WHERE C.FINPROD_ID = #{finprodId} ))


    AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
    )

SELECT FINPROD_ID hidCode, FINPROD_MARKET_ID code, FINPROD_ABBR name, FINPROD_ABBR shortName FROM FIN_PRODUCT
( FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{param}, '%')) OR FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{param}, '%')) )
AND FINPROD_TYPE2 = #{finprodType}
AND PROFIT_TYPE = #{PROFIT_TYPE}

SELECT B.SEC_ACCT_ID id, B.SEC_ACCT_NAME text FROM STL_SEC_ACCT_INFO B
AND ( B.SEC_ACCT_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND B.SEC_ACCT_ID = #{initValue, jdbcType=VARCHAR}

SELECT DISTINCT A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, A.FINPROD_ID, A.FINPROD_NAME, A.FINPROD_ABBR, TO_CHAR(A.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(A.IDATE, 'yyyy-MM-dd') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, B.TYPE_4 windtypeone, B.TYPE_6,
B.TYPE_9, B.TYPE_10, B.TYPE_11,
to_char(T1.VDATE, 'yyyy-MM-dd') EXERCISE_VDATE, to_char(T1.MDATE, 'yyyy-MM-dd') EXERCISE_MDATE, to_char(T1.ACT_EXERCISE_DATE, 'yyyy-MM-dd') EXERCISE_DATE, T1.EXERCISE_PRICE,
A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
INNER JOIN FIN_EXERCISE_PLAN T1 ON T1.FINPROD_ID = A.FINPROD_ID AND T1.EXERCISE_TYPE = '01' and T1.EXERCISE_DATE IS NOT NULL
AND T1.ACT_EXERCISE_DATE >= to_date(#{sysDate}, 'yyyy-MM-dd') AND T1.ACT_EXERCISE_DATE = ( SELECT min(TT1.ACT_EXERCISE_DATE) FROM FIN_EXERCISE_PLAN TT1 WHERE TT1.FINPROD_ID = T1.FINPROD_ID AND TT1.ACT_EXERCISE_DATE >= to_date(#{sysDate}, 'yyyy-MM-dd') AND TT1.EXERCISE_TYPE = '01' )
AND NOT EXISTS ( SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.FINPROD_ID = A.FINPROD_ID AND TT.VDATE = T1.VDATE AND TT.MDATE = T1.MDATE AND TT.PS='T39' AND TT.IS_CANCEL='N' AND TT.TRADE_STATUS ='01'
and TT.CHL_ID=#{chlId}
) AND NOT EXISTS ( SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.FINPROD_ID = A.FINPROD_ID AND TT.VDATE = T1.VDATE AND TT.MDATE = T1.MDATE AND TT.PS='T39'
AND TT.WORKFLOW_ID != #{workflowId}
)
AND EXISTS ( SELECT 1 FROM ( SELECT T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, T1.FINPROD_ID, T1.CDATE, DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1, '04', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT FROM PTL_SEC_POSITION T1 INNER JOIN FIN_EXERCISE_PLAN E1 ON E1.FINPROD_ID = T1.FINPROD_ID AND E1.EXERCISE_TYPE = '01' and E1.EXERCISE_DATE IS NOT NULL AND E1.EXERCISE_DATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM FIN_EXERCISE_PLAN TT1 WHERE TT1.FINPROD_ID = E1.FINPROD_ID AND E1.EXERCISE_DATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND TT1.EXERCISE_TYPE = '01' AND TT1.EXERCISE_DATE > E1.EXERCISE_DATE )
T1.HODING_TYPE IN ('03', '04', '06', '08')
and T1.SEC_ACCT_ID = #{chlId}
AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT FP WHERE FP.FINPROD_ID = T1.SEC_ACCT_ID)
AND T1.PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION TT1 WHERE T1.PORTFOLIO_ID = TT1.PORTFOLIO_ID AND T1.SEC_ACCT_ID = TT1.SEC_ACCT_ID AND T1.FINPROD_ID = TT1.FINPROD_ID AND T1.BRANCH = TT1.BRANCH AND T1.INV_AIM = TT1.INV_AIM AND T1.HODING_TYPE = TT1.HODING_TYPE AND T1.CDATE < TT1.CDATE and tt1.cdate <= E1.EXERCISE_DATE )
UNION ALL SELECT T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, T1.FINPROD_ID, T1.CDATE, T1.AMOUNT FROM PTL_SEC_POSITION_FLOW T1
AND T1.HODING_TYPE IN ('01')
and T1.SEC_ACCT_ID = #{chlId}
AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT FP WHERE FP.FINPROD_ID = T1.SEC_ACCT_ID)
AND T1.PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
) PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID AND PP.INVEST_YESORNO = 'Y' WHERE PSP.FINPROD_ID = A.FINPROD_ID AND T1.EXERCISE_DATE >= PSP.CDATE GROUP BY PSP.PORTFOLIO_ID, PSP.SEC_ACCT_ID, PSP.FINPROD_ID )
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_MARKET_ID = #{initValue}
AND A.IS_RIGHT = 'Y'
AND A.FINPROD_TYPE2 = #{finprodType}

SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_ID || ':' || A.PORTFOLIO_NAME text, B.IS_GUARANTEE object,
A.PROFIT_TYPE col
FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
and (A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_ID = #{initValue}
AND A.PORTFOLIO_TYPE = #{portType01}
AND A.INVEST_YESORNO = 'Y'
AND A.PORTFOLIO_TYPE != '02'
AND A.PARENT_PORTFOLIO_ID = #{parentPortfolioId}
AND A.PORTFOLIO_TYPE = #{portfolioType}
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PORTFOLIO_TYPE IN (#{portType}, #{portType1})
